env PATH="$PWD/.venv/bin:$PATH" python -c 'import ast, io, re, subprocess, sys, tokenize
BASE="8ff0355e32c6fb1ba67e4964dc12ba1b4c3e45b0"
PAT=re.compile(r"#\\s*(?:noqa\\b|type:\\s*ignore\\b|pragma:\\s*no cover\\b|pyright:|mypy:|ruff:|pylint:|(?:fmt|isort):\\s*(?:on|off|skip)\\b|nosec\\b|coding[:=]|[A-Za-z][\\w-]*(?:-ok|-via):)",re.I)
def source(ref,path): return subprocess.check_output(["git","show",f"{ref}:{path}"],text=True)
def norm(source,path):
 tree=ast.parse(source,filename=path,type_comments=True)
 for node in ast.walk(tree):
  if isinstance(node,(ast.Module,ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)) and node.body:
   head=node.body[0]
   if isinstance(head,ast.Expr) and isinstance(head.value,ast.Constant) and isinstance(head.value.value,str): node.body.pop(0)
  if isinstance(node,ast.TypeIgnore): node.lineno=0
 return ast.dump(tree,annotate_fields=True,include_attributes=False)
def protected(source):
 lines=source.splitlines()
 return (lines[0] if lines and lines[0].startswith("#!") else "",[lines[t.start[0]-1] for t in tokenize.generate_tokens(io.StringIO(source).readline) if t.type==tokenize.COMMENT and PAT.search(t.string)])
for path in sys.argv[1:]:
 before=source(BASE,path); after=source("HEAD",path)
 assert norm(before,path)==norm(after,path),f"runtime AST changed: {path}"
 assert protected(before)==protected(after),f"directive/shebang changed: {path}"
print(f"parent-to-final AST/directive PASS: {len(sys.argv)-1} paths")' tests/_bank_observer.py tests/_child_diag.py tests/_extra_guard.py tests/_git_counts.py tests/_git_floor.py tests/_git_upkeep.py tests/_isolation.py tests/_jira_shape_contract.py tests/_live_jira_confinement.py tests/_log_integrity.py tests/_nested_pytest.py tests/_repo_root.py tests/_stall_remote.py tests/_subprocess_isolation.py tests/_topology_template.py tests/_tree_scan.py tests/conftest.py tests/module_size_support.py
